        "n_points": "8",
        "replicates": "3",
        "vehicle_fraction": "0.5 % DMSO (kept constant across all wells)"
      }
    },
    {
      "card_id": "kinase-react",
      "instruction": "Add recombinant MAPK9, a peptide substrate (e.g., c‑Jun 1‑31), and ATP to each well; incubate under conditions that keep the reaction in the linear range.",
      "parameters": {
        "enzyme_concentration": "unresolved – typical starting point 5 ng/µL; would be optimized by a pilot linearity test",
        "substrate_concentration": "unresolved – often 10‑50 µM; select a concentration near the Km for the peptide",
        "ATP_concentration": "unresolved – 10 µM (≈ Km for MAPK9) to maintain sensitivity to competitive inhibition",
