        "temperature": "30 °C (standard for MAPK9 activity)"
      }
    },
    {
      "card_id": "kinase-detect",
      "instruction": "Terminate the kinase reaction, deplete remaining ATP with the ADP‑Glo™ reagent, then add the detection reagent and read luminescence.",
      "parameters": {
        "reagent_volumes": "as per kit protocol (e.g., 5 µL ADP‑Glo™ reagent + 5 µL detection reagent per 20 µL reaction)",
        "depletion_time": "40 min at room temperature",
        "detection_time": "10 min at room temperature before reading"
      }
    },
    {
      "card_id": "analyse",
      "instruction": "Normalize luminescence to 0 % inhibition (max activity) and 100 % inhibition (no‑enzyme blank); fit a four‑parameter logistic curve; report IC₅₀ with 95 % confidence interval and note assay limitations.",
      "parameters": {
        "fit_model": "four‑parameter logistic (Hill slope allowed to vary)",
        "acceptance_criteria": "R² > 0.90, Hill slope between –0.5 and –2, residuals randomly distributed"
